CREATE TABLE IF NOT EXISTS upcoming_sales (
    id VARCHAR(255) PRIMARY KEY, name VARCHAR(255), platform VARCHAR(100),
    start_date DATE, end_date DATE, banner_color VARCHAR(50), description TEXT
);

