CREATE TABLE IF NOT EXISTS vehicles (
    id VARCHAR(255) PRIMARY KEY, title VARCHAR(255), type VARCHAR(100),
    brand VARCHAR(100), price NUMERIC, image TEXT, rating NUMERIC,
    specs JSONB, platforms JSONB, is_ev BOOLEAN, ai_score INTEGER
);

-- Enable RLS and public policies
ALTER TABLE trending_deals ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_policies WHERE policyname = 'Allow public read access on trending_deals') THEN CREATE POLICY "Allow public read access on trending_deals" ON trending_deals FOR SELECT TO public USING (true); END IF; END $$;
ALTER TABLE upcoming_sales ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_policies WHERE policyname = 'Allow public read access on upcoming_sales') THEN CREATE POLICY "Allow public read access on upcoming_sales" ON upcoming_sales FOR SELECT TO public USING (true); END IF; END $$;
ALTER TABLE delivery_dishes ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_policies WHERE policyname = 'Allow public read access on delivery_dishes') THEN CREATE POLICY "Allow public read access on delivery_dishes" ON delivery_dishes FOR SELECT TO public USING (true); END IF; END $$;
ALTER TABLE vehicles ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_policies WHERE policyname = 'Allow public read access on vehicles') THEN CREATE POLICY "Allow public read access on vehicles" ON vehicles FOR SELECT TO public USING (true); END IF; END $$;
